export default {
  version: 1,
  name: "Moon Gravity",
  description: "Lower gravity lets the courier stay airborne longer and travel farther with each jump.",
  rules: [
    {
      id: "moon-gravity",
      each: "player",
      on: "tick",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        { type: "physics", target: "self", gravityScale: 0.5 }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Second Jump",
  description: "Press jump again while airborne to jump a second time. Landing restores your extra jump.",
  rules: [
    {
      id: "extra-air-jump",
      each: "player",
      on: "tick",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        { type: "physics", target: "self", airJumps: 1 }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Hold to Grow",
  description: "Hold interact to grow to 1.6 times your normal size wherever there is room. Release it to return to normal size.",
  rules: [
    {
      id: "grow-while-held",
      each: "player",
      on: "tick",
      when: {
        compare: {
          left: { field: "inputInteract" },
          op: "eq",
          right: 1
        }
      },
      actions: [
        {
          type: "physics",
          target: "self",
          playerScale: 1.6,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Lantern Gusts",
  description: "A gust pushes every movable crate to the right while it is within 240 world units of a lantern.",
  rules: [
    {
      id: "lantern-gust",
      each: "prop",
      on: "tick",
      when: {
        compare: {
          left: { field: "distanceToLantern" },
          op: "lte",
          right: 240
        }
      },
      actions: [
        {
          type: "physics",
          target: "self",
          windX: 0.12,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Rubber Ember",
  description: "The ember bounces like a rubber ball while dropped, until you pick it up again.",
  rules: [
    {
      id: "dropped-ember-bounce",
      each: "ember",
      on: "tick",
      when: {
        compare: {
          left: { field: "emberCarried" },
          op: "eq",
          right: 0
        }
      },
      actions: [
        {
          type: "material",
          target: "self",
          friction: 0.98,
          bounce: 0.9,
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Running Builds Your Jump",
  description: "The faster you run, the higher your next jump rises, up to 60% more jump strength.",
  rules: [
    {
      id: "running-strengthens-jumps",
      each: "player",
      on: "tick",
      when: { compare: { left: 1, op: "eq", right: 1 } },
      actions: [
        {
          type: "physics",
          target: "self",
          jumpStrength: {
            clamp: {
              value: {
                add: [
                  1,
                  {
                    mul: [
                      0.08,
                      { max: [{ field: "vx" }, { mul: [-1, { field: "vx" }] }] }
                    ]
                  }
                ]
              },
              min: 1,
              max: 1.6
            }
          },
          lifetime: 1
        }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Still Shadows",
  description: "Leave a crate still for half a second and its shadow from a nearby lit lantern becomes a solid bridge. Move the crate to dissolve the bridge.",
  rules: [
    {
      id: "still-prop-shadow-bridge",
      each: "prop",
      on: "tick",
      when: {
        compare: {
          left: { field: "stationaryTicks" },
          op: "gte",
          right: 30
        }
      },
      actions: [
        {
          type: "projectShadow",
          maxLength: 320,
          thickness: 12,
          lifetime: 1,
          solid: true
        }
      ]
    }
  ]
} satisfies RuleModule;
